body {
  margin: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #f9fafb;
  color: #111827;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#app {
  text-align: center;
  padding: 2rem;
  background: white;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
  width: 100%;
  max-width: 1200px;
}

import { renderSummaryCards } from './components/SummaryCards.js';
import { renderTransactionTable } from './components/TransactionTable.js';
import { openTransactionModal } from './components/TransactionModal.js';
import { renderChart } from './components/ChartWidget.js';

const STORAGE_KEY = 'app_transactions';

const state = {
    transactions: JSON.parse(localStorage.getItem(STORAGE_KEY)) || []
};

function saveState() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.transactions));
    window.dispatchEvent(new CustomEvent('data-updated'));
}

function updateUI() {
    renderSummaryCards(state.transactions);
    renderTransactionTable(state.transactions);
    renderChart(state.transactions);
}

// Event Listeners for State Mutations
window.addEventListener('add-transaction', (e) => {
    state.transactions.push(e.detail);
    saveState();
});

window.addEventListener('edit-transaction', (e) => {
    const index = state.transactions.findIndex(t => t.id === e.detail.id);
    if (index !== -1) {
        state.transactions[index] = e.detail;
        saveState();
    }
});

window.addEventListener('delete-transaction', (e) => {
    state.transactions = state.transactions.filter(t => t.id !== e.detail.id);
    saveState();
});

window.addEventListener('data-updated', updateUI);

// Initialization
document.addEventListener('DOMContentLoaded', () => {
    const addBtn = document.getElementById('add-transaction-btn');
    if (addBtn) {
        addBtn.addEventListener('click', () => openTransactionModal());
    }

    updateUI();
});

export function renderSummaryCards(transactions) {
  const container = document.getElementById('summarycards-container');
  if (!container) return;

  const totalIncome = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const totalExpense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const balance = totalIncome - totalExpense;

  container.innerHTML = `
    <div class="grid grid-cols-1 md:grid-cols-3 gap-4 p-4">
      <div class="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <h3 class="text-sm font-medium text-gray-500 uppercase tracking-wider">Balance</h3>
        <p class="text-2xl font-bold ${balance >= 0 ? 'text-green-600' : 'text-red-600'}">
          $${balance.toFixed(2)}
        </p>
      </div>
      <div class="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <h3 class="text-sm font-medium text-gray-500 uppercase tracking-wider">Income</h3>
        <p class="text-2xl font-bold text-green-600">+$${totalIncome.toFixed(2)}</p>
      </div>
      <div class="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <h3 class="text-sm font-medium text-gray-500 uppercase tracking-wider">Expenses</h3>
        <p class="text-2xl font-bold text-red-600">-$${totalExpense.toFixed(2)}</p>
      </div>
    </div>
  `;
}

export function openTransactionModal(existingTransaction = null) {
  const overlay = document.createElement('div');
  overlay.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50';
  overlay.id = 'transaction-modal-overlay';

  const modal = document.createElement('div');
  modal.className = 'bg-white p-6 rounded-lg shadow-xl w-full max-w-md';
  modal.innerHTML = `
    <h2 class="text-xl font-bold mb-4">${existingTransaction ? 'Edit' : 'Add'} Transaction</h2>
    <form id="transaction-form" class="space-y-4">
      <input type="hidden" id="edit-id" value="${existingTransaction?.id || ''}">
      <div>
        <label class="block text-sm font-medium">Description</label>
        <input type="text" id="desc" required class="w-full border rounded p-2" value="${existingTransaction?.description || ''}">
      </div>
      <div>
        <label class="block text-sm font-medium">Amount</label>
        <input type="number" id="amount" required step="0.01" class="w-full border rounded p-2" value="${existingTransaction?.amount || ''}">
      </div>
      <div>
        <label class="block text-sm font-medium">Type</label>
        <select id="type" class="w-full border rounded p-2">
          <option value="income" ${existingTransaction?.type === 'income' ? 'selected' : ''}>Income</option>
          <option value="expense" ${existingTransaction?.type === 'expense' ? 'selected' : ''}>Expense</option>
        </select>
      </div>
      <div class="flex justify-end gap-2 pt-4">
        <button type="button" id="cancel-btn" class="px-4 py-2 bg-gray-200 rounded">Cancel</button>
        <button type="submit" class="px-4 py-2 bg-blue-600 text-white rounded">Save</button>
      </div>
    </form>
  `;

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  const close = () => overlay.remove();

  overlay.querySelector('#cancel-btn').addEventListener('click', close);

  modal.querySelector('form').addEventListener('submit', (e) => {
    e.preventDefault();

    const id = document.getElementById('edit-id').value;
    const data = {
      id: id || Date.now().toString(),
      description: document.getElementById('desc').value,
      amount: parseFloat(document.getElementById('amount').value),
      type: document.getElementById('type').value
    };

    const eventName = id ? 'edit-transaction' : 'add-transaction';
    window.dispatchEvent(new CustomEvent(eventName, { detail: data }));

    close();
  });
}

import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

let chartInstance = null;

export function renderChart(transactions) {
  const container = document.getElementById('chartwidget-container');
  if (!container) return;

  container.innerHTML = '<canvas id="spending-chart"></canvas>';
  const ctx = document.getElementById('spending-chart').getContext('2d');

  if (chartInstance) {
    chartInstance.destroy();
  }

  const categoryTotals = transactions.reduce((acc, t) => {
    if (t.type === 'expense') {
      acc[t.category] = (acc[t.category] || 0) + parseFloat(t.amount);
    }
    return acc;
  }, {});

  const labels = Object.keys(categoryTotals);
  const data = Object.values(categoryTotals);

  chartInstance = new Chart(ctx, {
    type: 'pie',
    data: {
      labels: labels,
      datasets: [{
        label: 'Expenses by Category',
        data: data,
        backgroundColor: [
          '#ef4444', '#f97316', '#eab308', '#22c55e', 
          '#3b82f6', '#a855f7', '#ec4899'
        ],
      }]
    },
    options: {
      responsive: true,
      plugins: {
        legend: {
          position: 'bottom',
        },
        title: {
          display: true,
          text: 'Spending Distribution'
        }
      }
    }
  });
}

export function renderTransactionTable() {
  const container = document.getElementById('transactiontable-container');
  const transactions = JSON.parse(localStorage.getItem('transactions') || '[]');

  const filterValue = document.getElementById('search-input')?.value.toLowerCase() || '';
  const filtered = transactions.filter(t => 
    t.description.toLowerCase().includes(filterValue) || 
    t.category.toLowerCase().includes(filterValue)
  );

  container.innerHTML = `
    <div class="bg-white rounded-lg shadow p-6">
      <h2 class="text-lg font-bold mb-4">Transactions</h2>
      <input type="text" id="search-input" placeholder="Search transactions..." 
             class="w-full p-2 mb-4 border rounded" value="${filterValue}">
      <table class="w-full text-left border-collapse">
        <thead>
          <tr class="border-b">
            <th class="py-2">Description</th>
            <th class="py-2">Category</th>
            <th class="py-2">Amount</th>
            <th class="py-2">Action</th>
          </tr>
        </thead>
        <tbody id="transaction-body">
          ${filtered.map(t => `
            <tr class="border-b">
              <td class="py-2">${t.description}</td>
              <td class="py-2">${t.category}</td>
              <td class="py-2 ${t.type === 'expense' ? 'text-red-600' : 'text-green-600'}">
                ${t.type === 'expense' ? '-' : '+'}$${parseFloat(t.amount).toFixed(2)}
              </td>
              <td class="py-2">
                <button data-id="${t.id}" class="delete-btn text-red-500 hover:text-red-700">Delete</button>
              </td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;

  container.querySelector('#search-input').addEventListener('input', () => {
    renderTransactionTable();
  });

  container.querySelectorAll('.delete-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const id = e.target.getAttribute('data-id');
      window.dispatchEvent(new CustomEvent('delete-transaction', { detail: { id } }));
    });
  });
}
